# generated by tools/ail2py.py from callback_text_variants_main.ail; edit the .ail until onelang s16
from callback_text_pipeline import *
from ail import read_bytes, write_bytes
import sys

def trim_line(line: str) -> str:
    return line.strip()

def frame_line(line: str) -> str:
    return '[' + line + ']'

# Read once, then produce both UTF-8 variants using the same reusable pipeline.
def main() -> int:
    if len(sys.argv) != 3:
        print('usage: callback_text_variants <utf8-input> <output-prefix>', file=sys.stderr)
        return 2
    try:
        text = read_bytes(sys.argv[1]).decode()
        for mode in ['trim', 'frame']:
            operation: Callable[[str], str] = trim_line
            if mode == 'frame':
                operation = frame_line
            output = rewrite_lines(text, operation)
            write_bytes(sys.argv[2] + '.' + mode + '.txt', output.encode())
        return 0
    except UnicodeDecodeError:
        print('input must be UTF-8', file=sys.stderr)
        return 4
    except ValueError:
        print('invalid text transformation', file=sys.stderr)
        return 4
    except OSError:
        print('text variants file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
